template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 58mm;
  height: 40mm;
  padding: 1.8mm 4mm 1.4mm;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  background: #f0c21a;
  color: #2b1a12;
  font-family: Georgia, "Times New Roman", Times, serif;
  clip-path: polygon(
    0 0,
    100% 0,
    100% 7%,
    calc(100% - 2.4mm) 12%,
    calc(100% - 2.4mm) 88%,
    100% 93%,
    100% 100%,
    0 100%,
    0 93%,
    2.4mm 88%,
    2.4mm 12%,
    0 7%
  );
}
.headline {
  font-size: 15px;
  font-weight: 700;
  font-style: italic;
  letter-spacing: -0.02em;
  line-height: 1;
  text-align: center;
}
.name {
  margin-top: 1.2mm;
  font-size: 8px;
  font-weight: 600;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
  text-align: center;
  width: 100%;
}
.prices {
  margin-top: 0.8mm;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex: 1 1 auto;
  min-height: 0;
}
.old {
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  text-decoration: line-through;
  text-decoration-thickness: 0.35mm;
  opacity: 0.9;
  min-height: 1em;
}
.old:empty {
  display: none;
}
.now {
  margin-top: 0.4mm;
  width: 100%;
  text-align: center;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 0.95;
}
.footer {
  margin-top: auto;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.5mm;
  padding: 0.8mm 1.2mm;
  background: #fff;
  color: #2b1a12;
  border-radius: 0.4mm;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4mm;
  min-width: 0;
  flex: 1 1 auto;
}
img.barcode {
  height: 6.5mm;
  width: 100%;
  max-width: 42mm;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 6px;
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1;
  text-align: center;
  white-space: nowrap;
}
.meta {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 7px;
  font-weight: 700;
  line-height: 1;
  padding-bottom: 0.3mm;
  flex: 0 0 auto;
}
